css:
.sl-faq-split { background-color: var(--smartlearn-bg); padding-block: clamp(3rem, 7vw, 6rem); padding-inline: clamp(1rem, 4vw, 2rem); width: 100%; font-family: var(--smartlearn-body-font, system-ui, sans-serif); }
.sl-faq-split .sl-container { max-width: 1200px; margin-inline: auto; }
.sl-faq-split .sl-grid { display: grid; grid-template-columns: 1fr 1.5fr; gap: clamp(2rem, 5vw, 4rem); align-items: flex-start; }
.sl-faq-split .sl-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; color: var(--smartlearn-text); margin-bottom: 1rem; line-height: 1.2; }
.sl-faq-split .sl-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); line-height: 1.6; margin-bottom: 2rem; }
.sl-faq-split .sl-btn { display: inline-flex; align-items: center; justify-content: center; min-height: 44px; background: var(--smartlearn-btn-bg); color: var(--smartlearn-btn-text) !important; padding: 0.8rem 2rem; border-radius: var(--smartlearn-radius, 8px); font-weight: 600; text-decoration: none; transition: background-color 0.25s ease, transform 0.25s ease; }
.sl-faq-split .sl-btn:hover { background: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); transform: translateY(-2px); }
.sl-faq-split .sl-btn:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 3px; }
.sl-faq-split .sl-accordion { display: flex; flex-direction: column; gap: 1rem; }
.sl-faq-split .sl-item { background: var(--smartlearn-card-bg, transparent); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); border-radius: var(--smartlearn-radius, 8px); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); overflow: hidden; }
.sl-faq-split .sl-q-heading { margin: 0; font-size: inherit; }
.sl-faq-split .sl-q-btn { width: 100%; min-height: 44px; display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: 1.25rem 1.5rem; background: transparent; border: none; color: var(--smartlearn-text); font-family: var(--smartlearn-heading-font, inherit); font-size: 1.125rem; font-weight: 600; cursor: pointer; text-align: start; }
.sl-faq-split .sl-q-btn::after { content: '+'; font-size: 1.5rem; font-weight: 300; line-height: 1; color: var(--smartlearn-primary); flex-shrink: 0; }
.sl-faq-split .sl-item.active .sl-q-btn::after { content: '−'; }
.sl-faq-split .sl-q-btn:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: -3px; }
.sl-faq-split .sl-a-wrapper { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.3s ease; }
.sl-faq-split:not([data-sl-init="1"]) .sl-a-wrapper, .sl-faq-split .sl-item.active .sl-a-wrapper { grid-template-rows: 1fr; }
.sl-faq-split .sl-a-inner { overflow: hidden; }
.sl-faq-split .sl-a-content { padding: 0 1.5rem 1.5rem; color: var(--smartlearn-text-muted); line-height: 1.7; }
.sl-faq-split .sl-a-content p { margin: 0; }
@media (max-width: 900px) { .sl-faq-split .sl-grid { grid-template-columns: 1fr; } }
@media (prefers-reduced-motion: reduce) { .sl-faq-split .sl-btn, .sl-faq-split .sl-a-wrapper { transition: none; } .sl-faq-split .sl-btn:hover { transform: none; } }

js:
(function() {
  var init = function() {
    document.querySelectorAll('.sl-faq-split').forEach(function(section, sIdx) {
      if (section.dataset.slInit === '1') return;
      section.dataset.slInit = '1';
      var uid = 'sl-faq-split-' + sIdx + '-' + Math.random().toString(36).slice(2, 7);
      var items = section.querySelectorAll('.sl-item');
      items.forEach(function(item, iIdx) {
        var btn = item.querySelector('.sl-q-btn');
        var wrapper = item.querySelector('.sl-a-wrapper');
        if (!btn || !wrapper) return;
        var btnId = uid + '-btn-' + iIdx;
        var panelId = uid + '-panel-' + iIdx;
        btn.id = btnId;
        wrapper.id = panelId;
        btn.setAttribute('aria-controls', panelId);
        wrapper.setAttribute('aria-labelledby', btnId);
        var isOpen = item.classList.contains('active');
        btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
        wrapper.inert = !isOpen;
        btn.addEventListener('click', function() {
          var wasActive = item.classList.contains('active');
          items.forEach(function(other) {
            other.classList.remove('active');
            var ob = other.querySelector('.sl-q-btn');
            var ow = other.querySelector('.sl-a-wrapper');
            if (ob) ob.setAttribute('aria-expanded', 'false');
            if (ow) ow.inert = true;
          });
          if (!wasActive) {
            item.classList.add('active');
            btn.setAttribute('aria-expanded', 'true');
            wrapper.inert = false;
          }
        });
      });
    });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
